import java.util.*;
import java.io.*;

public class Main {
    static class SortedListIterator {
        SortedListIterator(List<List<Long>> lists) {
            // Write your solution here
        }

        boolean hasNext() {
            // Write your solution here
            return false;
        }

        long next() {
            // Write your solution here
            return 0;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int k = Integer.parseInt(st.nextToken());
        List<List<Long>> lists = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            int m = Integer.parseInt(st.nextToken());
            List<Long> l = new ArrayList<>();
            for (int j = 0; j < m; j++) l.add(Long.parseLong(st.nextToken()));
            lists.add(l);
        }
        int q = Integer.parseInt(st.nextToken());
        SortedListIterator it = new SortedListIterator(lists);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String op = st.nextToken();
            if (op.equals("hasNext")) sb.append(it.hasNext() ? "true" : "false").append('\n');
            else sb.append(it.next()).append('\n');
        }
        System.out.print(sb);
    }
}
